'use client';

import { motion } from 'framer-motion';

// Конфигурация элементов
const elements = [
  { id: 'img1', x: 93, y: 68, delay: 0.1, from: 'left' },
  { id: 'img2', x: 217, y: 195, delay: 0.25, from: 'right' },
  { id: 'img3', x: 63, y: 179, delay: 0.4, from: 'bottom' },
  { id: 'img4', x: 19, y: 177, delay: 0.55, from: 'left' },
  { id: 'img5', x: 41, y: 61, delay: 0.7, from: 'bottom' },
  { id: 'img6', x: 123, y: 24, delay: 0.85, from: 'top' },
];

// Определяем направление движения
const getDirection = (from: string) => {
  switch(from) {
    case 'left': return { x: -80, y: 0 };
    case 'right': return { x: 80, y: 0 };
    case 'top': return { x: 0, y: -80 };
    case 'bottom': return { x: 0, y: 80 };
    default: return { x: 0, y: 0 };
  }
};

export default function Logo() {
  return (
    <motion.div
      className='flex items-center justify-between gap-2'
      // Финальная пульсация после сборки
      animate={{
        scale: [1, 1.03, 1],
        opacity: [1, 0.9, 1],
      }}
      transition={{
        delay: 1.2, // Ждём, пока все элементы появятся
        duration: 0.8,
        repeat: 1,
        ease: "easeInOut",
      }}
    >
      <motion.svg 
        version="1.2" 
        xmlns="http://www.w3.org/2000/svg" 
        viewBox="0 0 270 257" 
        width="45" 
        height="45"
        // Общее появление
        initial={{ opacity: 0, scale: 0.1 }}
        animate={{ opacity: 1, scale: 1 }}
        transition={{ duration: 0.4, ease: "easeInOut" }}
        // Лёгкое покачивание после всего
        whileHover={{ scale: 1.05 }}
      >
        <defs>
				<image  width="133" height="132" id="img1" href="data:image/png;base64,"/>
				<image  width="35" height="35" id="img2" href="data:image/png;base64,"/>
				<image  width="140" height="52" id="img3" href="data:image/png;base64,"/>
				<image  width="36" height="36" id="img4" href="data:image/png;base64,"/>
				<image  width="100" height="115" id="img5" href="data:image/png;base64,"/>
				<image  width="37" height="36" id="img6" href="data:image/png;base64,"/>
			</defs>

        {elements.map((el) => {
          const direction = getDirection(el.from);
          return (
            <motion.g
              key={el.id}
              initial={{ 
                opacity: 0,
                x: direction.x,
                y: direction.y,
                rotate: el.from === 'left' ? -10 : el.from === 'right' ? 10 : 0,
                filter: "brightness(0.3)",
              }}
              animate={{ 
                opacity: 1,
                x: 0,
                y: 0,
                rotate: 0,
                filter: "brightness(1)",
              }}
              transition={{ 
                delay: el.delay,
                duration: 0.5,
                type: "spring",
                stiffness: 120,
                damping: 15,
              }}
            >
              <use href={`#${el.id}`} x={el.x} y={el.y} />
            </motion.g>
          );
        })}
      </motion.svg>

      {/* Текст с эффектом печати */}
      <motion.span 
        className="text-2xl font-bold tracking-tight bg-gradient-to-r from-[var(--accent-silver)] to-[var(--accent-purple-bright)] bg-clip-text text-transparent"
      >
        {"3VLab".split("").map((char, i) => (
          <motion.span
            key={i}
            initial={{ opacity: 0, x: -8, y: 5 }}
            animate={{ opacity: 1, x: 0, y: 0 }}
            transition={{
              delay: 0.9 + i * 0.08,
              duration: 0.3,
              type: "spring",
              stiffness: 150,
            }}
          >
            {char}
          </motion.span>
        ))}
      </motion.span>
    </motion.div>
  );
}